export default function Dashboard() {
  const navigate = useNavigate();
  const [role, setRole] = useState('');

  useEffect(() => {
    const userRole = localStorage.getItem('userRole');
    if (!userRole) {
      navigate('/login');
    } else {
      setRole(userRole);
    }
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('userRole');
    navigate('/');
  };

  const UserView = () => (
    <div dangerouslySetInnerHTML={{ __html: userHtml }} />
  );

  const DesignerView = () => (
    <div dangerouslySetInnerHTML={{ __html: designerHtml }} />
  );



  return (
    <div className="min-h-screen bg-gray-50/50">
      <header className="bg-white border-b px-6 py-4 flex flex-wrap justify-between items-center shadow-sm gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Dashboard Workspace</h2>
          <p className="text-sm text-gray-500">Masuk sebagai: <span className="font-semibold text-blue-600 uppercase">{role}</span></p>
        </div>
        <button 
          onClick={handleLogout} 
          className="border border-gray-300 text-gray-700 font-medium px-4 py-2 rounded-lg hover:bg-gray-100 transition-colors">
          Keluar (Logout)
        </button>
      </header>
      <main className="p-4 sm:p-6 lg:p-8 max-w-7xl mx-auto">
        {role === 'user' && <UserView />}
        {role === 'designer' && <DesignerView />}
        {role === 'admin' && <AdminPanel />}
      </main>
    </div>
  );
}
